'use strict';
window.ScenarioManager=(()=>{
 const $=id=>document.getElementById(id);let items=[],selected=new Set(),editing=null,serial=0;
 function message(t,error=false){$('scenario-notice').textContent=t;$('scenario-notice').className=error?'error':'hint';}
 function changed(){window.dispatchEvent(new Event('scenarios-updated'));render();}
 function describe(s){return `${s.kind==='parallel'?(s.bps>=0?'+':'')+s.bps+' bps':s.knots.map(k=>k.years+'Y: '+k.bps+' bps').join(' · ')} · ${s.role} · ${s.curve_ids.length?s.curve_ids.join(', '):'all curves'}`;}
 function validate(s){if(!s.name.trim()||s.name.length>100)throw Error('Enter a name of at most 100 characters.');if(!['parallel','tenor'].includes(s.kind)||!['both','discount','projection'].includes(s.role))throw Error('Invalid shock type or role.');const values=s.kind==='parallel'?[s.bps]:s.knots.map(k=>k.bps);if(values.some(v=>!Number.isFinite(v)||Math.abs(v)>5000))throw Error('Shocks must be between -5000 and +5000 bps.');if(s.kind==='tenor'){if(s.knots.length<2||s.knots.length>50)throw Error('Enter 2 to 50 tenor points.');if(s.knots.some(k=>!Number.isFinite(k.years)||k.years<0||k.years>150)||new Set(s.knots.map(k=>k.years)).size!==s.knots.length)throw Error('Tenors must be unique numbers from 0 to 150 years.');s.knots.sort((a,b)=>a.years-b.years);}return s;}
 function reset(s){editing=s?.id||null;$('scenario-name').value=s?.name||'';$('scenario-kind').value=s?.kind||'parallel';$('scenario-bps').value=s?.bps??100;$('scenario-role').value=s?.role||'both';$('scenario-target').value=s?.curve_ids[0]||'';$('scenario-knots').value=(s?.knots||[{years:0,bps:0},{years:2,bps:25},{years:5,bps:75},{years:10,bps:100}]).map(k=>`${k.years}, ${k.bps}`).join('\n');$('scenario-save').textContent=s?'Save changes':'Add scenario';toggle();}
 function toggle(){$('parallel-field').hidden=$('scenario-kind').value!=='parallel';$('tenor-field').hidden=$('scenario-kind').value!=='tenor';}
 function add(s){validate(s);if(!editing&&items.length>=10)throw Error('Keep at most 10 scenarios in this workspace.');s.id=editing||'SCENARIO-'+(++serial);const i=items.findIndex(x=>x.id===s.id);if(i>=0)items[i]=s;else items.push(s);selected.add(s.id);reset();changed();message('Scenario saved and selected for the next valuation.');}
 function render(){for(const id of ['scenario-list','run-scenarios'])$(id).replaceChildren();if(!items.length){$('scenario-list').textContent='No shocks defined yet. Add a scenario or start with a preset.';$('run-scenarios').textContent='Base only. Define shocks in Market curves to compare scenarios.';}
 for(const s of items){const row=document.createElement('div');row.className='scenario-row';const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=selected.has(s.id);check.onchange=()=>{check.checked?selected.add(s.id):selected.delete(s.id);changed();};const text=document.createElement('span');text.textContent=s.name;const small=document.createElement('small');small.textContent=describe(s);text.append(small);label.append(check,text);const edit=document.createElement('button');edit.className='secondary';edit.textContent='Edit';edit.onclick=()=>reset(s);const remove=document.createElement('button');remove.className='text-button';remove.textContent='Remove';remove.onclick=()=>{items=items.filter(x=>x.id!==s.id);selected.delete(s.id);if(editing===s.id)reset();changed();};row.append(label,edit,remove);$('scenario-list').append(row);
 const runLabel=document.createElement('label'),runCheck=document.createElement('input');runCheck.type='checkbox';runCheck.checked=selected.has(s.id);runCheck.setAttribute('aria-label',s.name);runCheck.onchange=()=>{runCheck.checked?selected.add(s.id):selected.delete(s.id);changed();};const span=document.createElement('span');span.textContent=s.name;span.title=describe(s);runLabel.append(runCheck,span);$('run-scenarios').append(runLabel);}
 $('scenario-count').textContent=`Base + ${selected.size} selected scenarios`;}
 $('scenario-kind').onchange=toggle;$('scenario-reset').onclick=()=>reset();
 $('scenario-form').onsubmit=e=>{e.preventDefault();try{const raw=$('scenario-knots').value.trim();const s={name:$('scenario-name').value.trim(),kind:$('scenario-kind').value,role:$('scenario-role').value,curve_ids:$('scenario-target').value?[$('scenario-target').value]:[]};if(s.kind==='parallel'){if(!$('scenario-bps').value.trim())throw Error('Enter the shock in bps.');s.bps=Number($('scenario-bps').value);}else s.knots=raw.split(/\n/).filter(x=>x.trim()).map(line=>{const v=line.trim().split(/[,;\s]+/);if(v.length!==2)throw Error('Each line must contain tenor years and shock bps, e.g. 5, 100.');return {years:Number(v[0]),bps:Number(v[1])};});add(s);}catch(e){message(e.message,true);}};
 for(const b of document.querySelectorAll('[data-shock]'))b.onclick=()=>{try{editing=null;const n=Number(b.dataset.shock);add({name:(n>0?'+':'')+n+' bps',kind:'parallel',bps:n,role:'both',curve_ids:[]});}catch(e){message(e.message,true);}};
 function targets(){const old=$('scenario-target').value;$('scenario-target').replaceChildren(new Option('All curves (including flat assumptions)',''),new Option('Flat assumptions only','FLAT OVERRIDE'));for(const c of CurveManager.all())$('scenario-target').add(new Option(c.id,c.id));if([...$('scenario-target').options].some(o=>o.value===old))$('scenario-target').value=old;}
 $('scenario-export').onclick=()=>{const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(items.flatMap(s=>(s.kind==='parallel'?[{years:'',bps:s.bps}]:s.knots).map(k=>({ID:s.id,Name:s.name,Type:s.kind,Role:s.role,'Curve ID':s.curve_ids[0]||'',Years:k.years,Bps:k.bps,Selected:selected.has(s.id)?'yes':'no'})))),'Scenarios');XLSX.writeFile(wb,'interest-rate-scenarios.xlsx');};
 window.addEventListener('curves-updated',targets);targets();reset();render();
 return {selected:()=>structuredClone(items.filter(s=>selected.has(s.id))),all:()=>structuredClone(items),describe};
})();
